/* Case material points: demo data, no production service calls. */
function v4Material(index){const m=MATERIAL_CATALOG[index];return {id:'TG'+String(index+1).padStart(3,'0'),name:m.name,model:String(10001+index),brand:m.brand||'',category:m.categoryName||m.category||'装饰材料',image:m.image,source:'天工云仓物料库',link:'https://tiangong.example/material/TG'+String(index+1).padStart(3,'0')};}
function v4Clone(value){return JSON.parse(JSON.stringify(value));}
V3_ADMIN_ITEMS.effect.forEach((item,index)=>{
 item.caseId='case-'+index;
 item.points=index<3?[
  {id:'p-wall',box:{x:9,y:15,w:14,h:24},material:v4Material(0)},
  {id:'p-wood',box:{x:69,y:14,w:13,h:27},material:v4Material(1)},
  {id:'p-rug',box:{x:35,y:76,w:30,h:13},material:v4Material(2)}
 ]:[];
});
v4SyncLibrary('effect');
S.v4PointSelected=null;S.v4Swap=null;S.v4PointEditor=null;
function v4PointCenter(point){return point.box?{x:point.box.x+point.box.w/2,y:point.box.y+point.box.h/2}:{x:point.x,y:point.y};}
function v4MaterialCard(material,caption=''){return material?`<div class="v4-material-summary"><img src="${v3Esc(material.image)}" alt="${v3Esc(material.name)}"><div>${caption?`<small>${caption}</small>`:''}<b>${v3Esc(material.name)}</b><span>${v3Esc(material.category)}</span><span>型号：${v3Esc(material.model||'未提供')}</span></div></div>`:'<div class="v4-original-unknown">此位置未配置原物料</div>';}
function v4Scene(image,points,mode){
 const selected=mode==='case'?S.v4PointSelected:S.v4Swap?.selected;
 const active=points.find(p=>p.id===selected);
 const dots=points.map((p,index)=>{const c=v4PointCenter(p);return `<button class="v4-hotspot ${selected===p.id?'on':''} ${p.replacement?'changed':''}" style="left:${c.x}%;top:${c.y}%" aria-label="点位 ${index+1}${p.material?' '+v3Esc(p.material.name):' 新位置'}" aria-expanded="${selected===p.id}" onclick="event.stopPropagation();v4SelectPoint('${mode}','${p.id}')"><span>${mode==='swap'?index+1:''}</span></button>`;}).join('');
 let popup='';if(active){const c=v4PointCenter(active);popup=`<aside class="v4-point-popup" style="left:clamp(8px,calc(${c.x}% - 110px),calc(100% - 228px));top:clamp(8px,calc(${c.y}% ${c.y>48?'- 290px':'+ 25px'}),calc(100% - 294px))" onclick="event.stopPropagation()"><button class="v4-popup-close" aria-label="关闭物料信息" onclick="v4ClosePoint('${mode}')">×</button>${active.material?`<img src="${v3Esc(active.material.image)}" alt="${v3Esc(active.material.name)}"><div class="v4-point-copy"><small>原物料</small><b>${v3Esc(active.material.name)}</b><span>${v3Esc(active.material.category)}</span><span class="v5-point-model">型号：${v3Esc(active.material.model||'未提供')}</span><span class="v5-point-brand">${v3Esc(active.material.brand||'未提供')}</span></div>`:'<div class="v4-point-copy"><b>新标记位置</b><span>选择物料替换此处</span></div>'}${mode==='swap'?`<button class="v3-btn primary" onclick="v4OpenSwapPicker('${active.id}')">${active.replacement?'更换替换物料':'替换此处'}</button>`:''}</aside>`;}
 return `<div class="v4-scene ${mode==='swap'&&S.v4Swap.adding?'adding':''}" data-v4-scene><div class="v4-image-plane" onclick="v4SceneClick(event,'${mode}')"><img class="v4-scene-image" src="${v3Esc(image)}" alt="空间效果图" onload="v4LayoutScenes()" draggable="false">${dots}${popup}</div>${mode==='swap'&&S.v4Swap.adding?'<div class="v4-scene-tip">点击要替换的位置</div>':''}</div>`;
}
function v4LayoutScenes(){document.querySelectorAll('[data-v4-scene]').forEach(host=>{const plane=host.querySelector('.v4-image-plane'),img=plane?.querySelector('.v4-scene-image');if(!img?.naturalWidth)return;const scale=Math.min(host.clientWidth/img.naturalWidth,host.clientHeight/img.naturalHeight);const w=img.naturalWidth*scale,h=img.naturalHeight*scale;Object.assign(plane.style,{width:w+'px',height:h+'px',left:(host.clientWidth-w)/2+'px',top:(host.clientHeight-h)/2+'px'});});}
window.addEventListener('resize',v4LayoutScenes);
function v4SelectPoint(mode,id){if(mode==='case')S.v4PointSelected=S.v4PointSelected===id?null:id;else {const swap=S.v4Swap,pending=swap.pending?.find(m=>m.queueId===swap.pendingId);if(pending){const point=swap.points.find(p=>p.id===id);if(point)point.replacement=pending.material;swap.pending=swap.pending.filter(m=>m.queueId!==pending.queueId);swap.pendingId=null;}swap.selected=id;swap.adding=false;}render();}
function v4ClosePoint(mode){if(mode==='case')S.v4PointSelected=null;else S.v4Swap.selected=null;render();}
function v4SceneClick(event,mode){if(mode==='case'){v4ClosePoint(mode);return;}const swap=S.v4Swap,pending=swap.pending?.find(m=>m.queueId===swap.pendingId);if(!swap.adding||!pending){v4ClosePoint(mode);return;}const rect=event.currentTarget.getBoundingClientRect();const point={id:'custom-'+Date.now(),x:(event.clientX-rect.left)/rect.width*100,y:(event.clientY-rect.top)/rect.height*100,material:null,replacement:pending.material};swap.points.push(point);swap.pending=swap.pending.filter(m=>m.queueId!==pending.queueId);swap.pendingId=null;swap.selected=point.id;swap.adding=false;render();}
v4CaseDetail=function(){const item=V3_EFFECT_PRESETS[S.v4CaseIndex];if(!item)return v4CaseScreen();return v3Shell(item.name,`<div class="v4-case-view">${v4Scene(item.image,item.points||[],'case')}<footer class="v4-case-footer"><span>${v3Esc(v4CategoryLabel('effect',item))}${item.points?.length?'　·　点击图中圆点查看物料':''}</span><button class="v3-btn primary" onclick="v4StartCaseSwap()">替换材质</button></footer></div>`,'cases');};
function v4StartSwap(item,backTarget){S.inputImage=item.image;S.inputName=item.name||'效果图';S.v4Swap={points:v4Clone(item.points||[]),pending:[],pendingId:null,selected:null,adding:false,backTarget};S.materialCandidates=[];S.marks=[];S.materialSourceModal='';S.v4SwapPicker=null;S.page='mark';render();}
function v4StartCaseSwap(){const item=V3_EFFECT_PRESETS[S.v4CaseIndex];if(item)v4StartSwap(item,'caseDetail');}
confirmEffectSource=function(){if(S.effectSelection)v4StartSwap(S.effectSelection,'effectSelect');};
const v4PointStartRoute=startRoute;
startRoute=function(route){S.v4Swap=null;S.v4PointSelected=null;v4PointStartRoute(route);};
const v4PointGenerated=startMaterialFromGenerated;
startMaterialFromGenerated=function(){S.v4Swap=null;v4PointGenerated();};
const v4PointMarker=markerScreen;
markerScreen=function(){if(!S.v4Swap)return v4PointMarker();const swap=S.v4Swap,count=swap.points.filter(p=>p.replacement).length;
 const cards=swap.points.map((p,i)=>`<article data-point-id="${p.id}" class="v4-swap-row ${swap.selected===p.id?'on':''}"><button class="v4-row-select" onclick="v4SelectPoint('swap','${p.id}')"><span class="v4-point-number">${i+1}</span><b>${p.material?v3Esc(p.material.name):'新标记位置'}</b><small>${p.replacement?'待替换':'保持原样'}</small></button>${v4MaterialCard(p.material,'原物料')}${p.replacement?`<div class="v4-swap-arrow">↓ 替换为</div>${v4MaterialCard(p.replacement)}<div class="v4-row-actions"><button onclick="v4OpenSwapPicker('${p.id}')">重新选择</button><button onclick="v4UndoSwap('${p.id}')">撤销替换</button></div>`:`<button class="v4-select-new" onclick="v4OpenSwapPicker('${p.id}')">＋ 选择新物料</button>${!p.material?`<button class="v4-remove-new" onclick="v4UndoSwap('${p.id}')">删除标记</button>`:''}`}</article>`).join('');
 return v3Shell('替换材质',`<div class="v4-swap-layout"><div class="v4-swap-main">${v4Scene(S.inputImage,swap.points,'swap')}<div class="v4-swap-toolbar"><span>${swap.adding?'已选物料，点击图片确定替换位置':'先添加物料，再选位置；也可点击已有点位替换'}</span>${swap.adding?'<button class="v3-btn" onclick="S.v4Swap.adding=false;S.v4Swap.pendingId=null;render()">取消选位</button>':''}</div></div><aside class="v4-swap-side"><header><div><h2>物料</h2><span>${count} 处待替换${swap.pending?.length?' · '+swap.pending.length+' 个待选位置':''}</span></div><button class="v3-btn" onclick="v4OpenSwapPicker()">＋ 添加物料</button></header><div class="v4-swap-rows">${v4PendingCards()}${cards||(!swap.pending?.length?'<div class="v4-empty">暂无物料<br><br>先添加物料，再点击图片选择位置</div>':'')}</div><footer><small>${swap.pending?.length?'待选位置的物料不会参与生成':'未选择的位置保持原样'}</small><button class="v3-btn primary" ${count?'':'disabled'} onclick="v4GenerateSwap()">生成替换效果${count?' · '+count+' 处':''}</button></footer></aside></div>`,swap.backTarget,S.v4SwapPicker?v4SwapPickerDialog():'');};
function v4UndoSwap(id){const p=S.v4Swap.points.find(p=>p.id===id);if(!p)return;if(p.material)delete p.replacement;else S.v4Swap.points=S.v4Swap.points.filter(p=>p.id!==id);S.v4Swap.selected=null;render();}
function v4OpenSwapPicker(id){S.v4Swap.pendingId=null;S.v4Swap.adding=false;S.v4SwapPicker={pointId:id||null,query:''};render();}
function v4ChoosePending(id){S.v4Swap.pendingId=id;S.v4Swap.adding=true;S.v4Swap.selected=null;render();}
function v4RemovePending(id){S.v4Swap.pending=S.v4Swap.pending.filter(m=>m.queueId!==id);if(S.v4Swap.pendingId===id){S.v4Swap.pendingId=null;S.v4Swap.adding=false;}render();}
function v4PendingCards(){const swap=S.v4Swap;return (swap.pending||[]).map(m=>`<article class="v4-pending-material ${swap.pendingId===m.queueId?'on':''}"><button class="v4-pending-select" onclick="v4ChoosePending('${m.queueId}')">${v4MaterialCard(m.material)}<span>${swap.pendingId===m.queueId?'点击图片选择位置':'待选位置 · 点击选中'}</span></button><button class="v4-pending-remove" aria-label="移除待定位物料 ${v3Esc(m.material.name)}" onclick="v4RemovePending('${m.queueId}')">×</button></article>`).join('');}
function v4SwapPickerDialog(){const state=S.v4SwapPicker,p=S.v4Swap.points.find(p=>p.id===state.pointId);return `<div class="v3-mask"><section class="v3-dialog v4-material-picker" role="dialog" aria-modal="true" aria-label="选择替换物料"><header class="v3-dialog-head"><div><h2>${state.pointId?'选择替换物料':'添加物料'}</h2><p>${p?.material?'替换：'+v3Esc(p.material.name):'添加物料后，在图片上选择位置'}</p></div><button class="v3-icon-btn" aria-label="关闭选择物料" onclick="S.v4SwapPicker=null;render()">×</button></header><div class="v4-picker-tools"><b>天工云仓物料库</b><form onsubmit="event.preventDefault();S.v4SwapPicker.query=this.elements.query.value;render()"><input name="query" aria-label="搜索物料" placeholder="搜索物料名称或分类" value="${v3Esc(state.query)}"><button class="v3-btn">搜索</button></form><label class="v3-btn v4-local-upload">本地上传<input hidden type="file" accept="image/png,image/jpeg" onchange="v4SwapLocalFile(event)"></label></div><div class="v4-material-options">${MATERIAL_CATALOG.map((m,i)=>({m:v4Material(i),i})).filter(({m})=>!state.query||(m.name+m.category).includes(state.query.trim())).map(({m,i})=>`<button class="v4-material-option" onclick="v4ChooseSwapMaterial(${i})"><img src="${v3Esc(m.image)}" alt="${v3Esc(m.name)}"><b>${v3Esc(m.name)}</b><small>${v3Esc(m.category)}</small></button>`).join('')||v4Empty()}</div><footer class="v3-dialog-foot"><button class="v3-btn" onclick="S.v4SwapPicker=null;render()">取消</button></footer></section></div>`;}
function v4ChooseSwapMaterial(index){v4ApplySwapMaterial(v4Material(index));}
function v4ApplySwapMaterial(material){const swap=S.v4Swap,p=swap.points.find(p=>p.id===S.v4SwapPicker?.pointId);if(p){p.replacement=material;swap.selected=p.id;}else if(S.v4SwapPicker&&!S.v4SwapPicker.pointId){const pending={queueId:'pending-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),material};swap.pending||=[];swap.pending.push(pending);swap.pendingId=pending.queueId;swap.adding=true;swap.selected=null;}else return;S.v4SwapPicker=null;render();}
function v4SwapLocalFile(event){const file=event.target.files?.[0];if(!file)return;if(!/^image\/(png|jpeg)$/.test(file.type)||file.size>10*1024*1024){toast('请选择 10 MB 以内的 JPG 或 PNG');return;}v4ApplySwapMaterial({id:'local-'+Date.now(),name:file.name.replace(/\.[^.]+$/,''),category:'本地上传',image:URL.createObjectURL(file),source:'本地上传'});}
function v4GenerateSwap(){const points=S.v4Swap.points.filter(p=>p.replacement);if(!points.length)return;S.materialCandidates=points.map(p=>({...p.replacement,id:'swap-'+p.id}));S.marks=points.map(p=>({...v4PointCenter(p),materialId:'swap-'+p.id,originalMaterial:p.material?{...p.material}:null}));replaceMaterial();}
const v4PointFinish=finishV3Replacement;
finishV3Replacement=function(){v4PointFinish();if(S.v4Swap&&V3_CALL_LOGS[0]){V3_CALL_LOGS[0].points.forEach((p,i)=>{p.originalMaterial=S.marks[i]?.originalMaterial||null;});}};
/* Admin editor: draft rectangles locate points only; no segmentation or crop mask. */
const v4PointAdmin=admin;
admin=function(){let html=v4PointAdmin();if(S.adminSection!=='effect'||S.v4CategoryKind)return html;const template=document.createElement('template');template.innerHTML=html;template.content.querySelectorAll('.v3-admin-actions').forEach(actions=>{const edit=actions.querySelector('button[onclick^="openAdminEdit"]');if(!edit)return;const index=Number(edit.getAttribute('onclick').match(/\((\d+)\)/)[1]);actions.insertAdjacentHTML('beforeend',`<button onclick="v4OpenPointEditor(${index})">点位配置${V3_ADMIN_ITEMS.effect[index].points?.length?' ('+V3_ADMIN_ITEMS.effect[index].points.length+')':''}</button>`);});return template.innerHTML+(S.v4PointEditor?v4PointEditorDialog():'');};
function v4OpenPointEditor(index){const item=V3_ADMIN_ITEMS.effect[index];S.v4PointEditor={index,points:v4Clone(item.points||[]),active:null,drawing:false,redraw:null,error:''};render();}
function v4PointEditorDialog(){const e=S.v4PointEditor,item=V3_ADMIN_ITEMS.effect[e.index];const boxes=e.points.map((p,i)=>`<button aria-label="选中点位 ${i+1}" class="v4-admin-box ${e.active===p.id?'on':''}" style="left:${p.box.x}%;top:${p.box.y}%;width:${p.box.w}%;height:${p.box.h}%" onpointerdown="if(!S.v4PointEditor.drawing)event.stopPropagation()" onclick="if(!S.v4PointEditor.drawing){S.v4PointEditor.active='${p.id}';render()}"><span>${i+1}</span></button>`).join('');
 return `<div class="v3-mask"><section class="v4-point-editor" role="dialog" aria-modal="true" aria-label="效果图点位配置"><header class="v3-dialog-head"><div><h2>点位配置 · ${v3Esc(item.name)}</h2><p>画框确定点位中心，再绑定天工云仓物料；点位选填，最多10个</p></div><button class="v3-icon-btn" aria-label="关闭点位配置" onclick="S.v4PointEditor=null;render()">×</button></header><div class="v4-editor-body"><div class="v4-editor-left"><div class="v4-editor-tools"><span>${e.drawing?'在图片上拖动画框':'方框仅用于定位'}</span><button class="v3-btn ${e.drawing?'':'primary'}" ${e.points.length>=10&&!e.drawing?'disabled':''} onclick="v4AddPoint()">${e.drawing?'取消画框':'＋ 添加点位'}</button></div><div class="v4-scene ${e.drawing?'adding':''}" data-v4-scene><div class="v4-image-plane" onpointerdown="v4DrawPoint(event)"><img class="v4-scene-image" src="${v3Esc(item.image)}" alt="配置点位的效果图" draggable="false" onload="v4LayoutScenes()">${boxes}</div></div></div><div class="v4-editor-right"><h3>点位物料配置 <small>${e.points.length} / 10 个点位</small></h3><p class="v4-demo-note">当前演示使用示例链接，不连接正式物料库。</p>${e.points.map((p,i)=>`<article class="v4-admin-point-row ${e.active===p.id?'on':''}"><header><b>点位 ${i+1}</b><button onclick="v4RedrawPoint('${p.id}')">重画位置</button><button onclick="v4DeletePoint('${p.id}')">删除</button></header><label>天工云仓物料链接<input aria-label="点位 ${i+1} 物料链接" placeholder="粘贴物料详情链接" value="${v3Esc(p.link||p.material?.link||'')}" oninput="v4UpdatePointLink('${p.id}',this.value)"></label><div class="v4-link-actions"><select aria-label="点位 ${i+1} 示例物料" onchange="v4SetSampleLink('${p.id}',this.value)"><option value="">选择示例链接</option>${MATERIAL_CATALOG.map((m,j)=>`<option value="${j}">${v3Esc(m.name)}</option>`).join('')}</select><button class="v3-btn" onclick="v4ResolvePointLink('${p.id}')">获取物料</button></div><div id="v4-preview-${p.id}">${p.material?v4MaterialCard(p.material):'<small class="v4-unbound">尚未绑定物料</small>'}</div></article>`).join('')||'<div class="v4-empty">尚未配置点位<br><br>可以直接保存，案例仍会展示</div>'}</div></div><footer class="v3-dialog-foot"><span class="v4-editor-error" role="alert">${v3Esc(e.error)}</span><button class="v3-btn" onclick="S.v4PointEditor=null;render()">取消</button><button class="v3-btn primary" onclick="v4SavePoints()">保存配置</button></footer></section></div>`;}
function v4AddPoint(){const e=S.v4PointEditor;if(!e.drawing&&e.points.length>=10){e.error='每个案例最多配置10个点位';render();return;}e.drawing=!e.drawing;e.redraw=null;e.error='';render();}
function v4UpdatePointLink(id,value){const p=S.v4PointEditor.points.find(p=>p.id===id);p.link=value;p.material=null;const preview=document.getElementById('v4-preview-'+id);if(preview)preview.innerHTML='<small class="v4-unbound">链接已变更，请获取物料</small>';}
function v4SetSampleLink(id,index){if(index==='')return;const p=S.v4PointEditor.points.find(p=>p.id===id);p.link=v4Material(Number(index)).link;p.material=null;S.v4PointEditor.active=id;render();}
function v4ResolvePointLink(id){const e=S.v4PointEditor,p=e.points.find(p=>p.id===id);const material=MATERIAL_CATALOG.map((_,i)=>v4Material(i)).find(m=>m.link===(p.link||p.material?.link||'').trim());if(!material){e.error='当前 Demo 仅支持示例链接，请选择示例链接后获取物料。';render();return;}p.material=material;p.link=material.link;e.error='';render();}
function v4RedrawPoint(id){S.v4PointEditor.active=id;S.v4PointEditor.redraw=id;S.v4PointEditor.drawing=true;render();}
function v4DeletePoint(id){const e=S.v4PointEditor;e.points=e.points.filter(p=>p.id!==id);if(e.active===id)e.active=null;e.error='';render();}
function v4DrawPoint(event){const e=S.v4PointEditor;if(!e?.drawing||event.button!==0)return;if(!e.redraw&&e.points.length>=10){e.error='每个案例最多配置10个点位';e.drawing=false;render();return;}event.preventDefault();const plane=event.currentTarget,rect=plane.getBoundingClientRect();const pos=ev=>({x:Math.max(0,Math.min(100,(ev.clientX-rect.left)/rect.width*100)),y:Math.max(0,Math.min(100,(ev.clientY-rect.top)/rect.height*100))});const start=pos(event);let box=null;const ghost=document.createElement('div');ghost.className='v4-admin-box v4-draw-ghost';plane.appendChild(ghost);plane.setPointerCapture(event.pointerId);
 const move=ev=>{const p=pos(ev);box={x:Math.min(start.x,p.x),y:Math.min(start.y,p.y),w:Math.abs(p.x-start.x),h:Math.abs(p.y-start.y)};Object.assign(ghost.style,{left:box.x+'%',top:box.y+'%',width:box.w+'%',height:box.h+'%'});};
 const finish=ev=>{plane.removeEventListener('pointermove',move);plane.removeEventListener('pointerup',finish);plane.removeEventListener('pointercancel',cancel);if(plane.hasPointerCapture(event.pointerId))plane.releasePointerCapture(event.pointerId);if(box&&box.w>1&&box.h>1){if(e.redraw)e.points.find(p=>p.id===e.redraw).box=box;else{const point={id:'point-'+Date.now(),box,material:null,link:''};e.points.push(point);e.active=point.id;}e.drawing=false;e.redraw=null;e.error='';}render();};
 const cancel=()=>{box=null;finish();};plane.addEventListener('pointermove',move);plane.addEventListener('pointerup',finish);plane.addEventListener('pointercancel',cancel);
}
function v4SavePoints(){const e=S.v4PointEditor;if(e.points.length>10){e.error='每个案例最多配置10个点位';render();return;}if(e.points.some(p=>p.material&&!/^[0-9]{1,5}$/.test(p.material.model||''))){e.error='物料型号须为1至5位数字，请重新获取物料';render();return;}if(e.points.some(p=>!p.material)){e.error='请为已画出的点位绑定物料，或删除不需要的点位。';render();return;}V3_ADMIN_ITEMS.effect[e.index].points=v4Clone(e.points);V3_ADMIN_ITEMS.effect[e.index].updatedAt=v3Now();v4SyncLibrary('effect');S.v4PointEditor=null;render();}
const v4PointCaseScreen=v4CaseScreen;
v4CaseScreen=function(){return v4PointCaseScreen().replaceAll("S.page='caseDetail';render()", "S.v4PointSelected=null;S.page='caseDetail';render()");};
const v4PointAdminFile=v3AdminFileChosen;
v3AdminFileChosen=function(event){const file=event.target.files?.[0];if(S.adminSection==='effect'&&file&&/^image\/(png|jpeg)$/.test(file.type)&&file.size<=10*1024*1024)S.v3AdminForm.points=[];v4PointAdminFile(event);};
const v4PointCompare=compareScreen;
compareScreen=function(){let html=v4PointCompare();if(!S.v4Swap)return html;const template=document.createElement('template');template.innerHTML=html;const list=template.content.querySelector('.v3-compare-materials');list.innerHTML=S.v4Swap.points.filter(p=>p.replacement).map((p,i)=>`<article class="v4-swap-row"><div class="v4-result-point">位置 ${i+1}</div>${v4MaterialCard(p.material,'原物料')}<div class="v4-swap-arrow">↓ 替换为</div>${v4MaterialCard(p.replacement)}</article>`).join('');return template.innerHTML;};
const v4PointRender=render;
render=function(){v4PointRender();requestAnimationFrame(()=>{v4LayoutScenes();if(S.page==='mark'&&S.v4Swap?.selected){const row=document.querySelector('.v4-swap-row.on');if(row)row.scrollIntoView({block:'nearest'});}if(S.v4PointEditor?.active){const row=document.querySelector('.v4-admin-point-row.on');if(row)row.scrollIntoView({block:'nearest'});}});};
document.addEventListener('keydown',event=>{if(event.key!=='Escape')return;if(S.v4SwapPicker)S.v4SwapPicker=null;else if(S.v4PointEditor)S.v4PointEditor=null;else if(S.page==='caseDetail')S.v4PointSelected=null;else if(S.page==='mark'&&S.v4Swap){S.v4Swap.selected=null;S.v4Swap.adding=false;}else return;render();});
render();
